// static
bool StructTraits<::crosapi::mojom::RemovableStorageDevice::DataView, ::crosapi::mojom::RemovableStorageDevicePtr>::Read(
    ::crosapi::mojom::RemovableStorageDevice::DataView input,
    ::crosapi::mojom::RemovableStorageDevicePtr* output) {
  bool success = true;
  ::crosapi::mojom::RemovableStorageDevicePtr result(::crosapi::mojom::RemovableStorageDevice::New());
  
      if (success && !input.ReadStorageUnitId(&result->storage_unit_id))
        success = false;
      if (success)
        result->capacity = input.capacity();
      if (success && !input.ReadVendor(&result->vendor))
        success = false;
      if (success && !input.ReadModel(&result->model))
        success = false;
      if (success)
        result->removable = input.removable();
  *output = std::move(result);
  return success;
}

